<script setup lang="ts">import{onMounted,ref}from'vue';import http from'../api/http';const rows=ref<any[]>([]);async function load(){const{data}=await http.get('/mdm/boms',{params:{page:1,size:50}});rows.value=data.data.content}async function submit(r:any){await http.post(`/mdm/boms/${r.id}/submit`);load()}onMounted(load)</script><template><el-card><template #header>BOM 权威主数据</template><el-alert title="BOM 子件仅允许引用已发布物料；审批完成后，ERP/MES 消费当前有效版本。" type="info" :closable="false"/><el-table :data="rows" style="margin-top:16px"><el-table-column prop="bomCode" label="编码"/><el-table-column prop="bomName" label="名称"/><el-table-column prop="productCode" label="产品"/><el-table-column prop="bomVersion" label="版本"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='DRAFT'||row.status==='REJECTED'" size="small" @click="submit(row)">提交审批</el-button></template></el-table-column></el-table></el-card></template>
